import { useState } from "react";
import { Autocompletar } from "./Autocompletar.jsx";

const distritos = [
  "Barranco",
  "Breña",
  "Chorrillos",
  "Jesús María",
  "La Molina",
  "La Victoria",
  "Lince",
  "Los Olivos",
  "Magdalena del Mar",
  "Miraflores",
  "Pueblo Libre",
  "San Borja",
  "San Isidro",
  "San Juan de Lurigancho",
  "San Miguel",
  "Santiago de Surco",
  "Surquillo",
];

export default function App() {
  const [distrito, setDistrito] = useState("");

  return (
    <main style={{ maxWidth: 420, margin: "2rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>Dirección de entrega</h1>
      <p>Escribe tu distrito (por ejemplo, "san") y usa las flechas.</p>
      <Autocompletar opciones={distritos} onElegir={setDistrito} />
      {distrito && <p>Entregaremos en {distrito}.</p>}
    </main>
  );
}
